  rankdir=LR;
  graph [bgcolor="white", pad=0.2, nodesep=0.35, ranksep=0.55];
  node [fontname="Arial", fontsize=10, style="rounded,filled",
        color="#526477", penwidth=1.2];
  edge [fontname="Arial", fontsize=9, color="#526477", arrowsize=0.8];

  data [label="Full dataset", shape=cylinder,
        fillcolor="#FFF1A8"];
  split [label="Split into 5 folds", fillcolor="#D9EAFE"];

  folds [shape=plain, label=<
    <TABLE BORDER="0" CELLBORDER="1" CELLSPACING="0" CELLPADDING="5">
      <TR><TD BGCOLOR="#E8EAF0"><B>Rotation</B></TD>
          <TD BGCOLOR="#E8EAF0"><B>Fold 1</B></TD>
          <TD BGCOLOR="#E8EAF0"><B>Fold 2</B></TD>
          <TD BGCOLOR="#E8EAF0"><B>Fold 3</B></TD>
